-- يضيف بند Google Analytics إلى سياسة الخصوصية (مرة واحدة فقط؛ إعادة التشغيل لا تكرره).
BEGIN;
UPDATE policies
   SET body = body || E'\n' || $p$- القياس والتحليلات: نستخدم Google Analytics لقياس زيارات صفحات الموقع العامة وتحسين تجربتك، وذلك فقط بعد موافقتك على الشريط الذي يظهر عند أول زيارة، وتقدر ترفض فلا نقيس زيارتك. لا نفعّل القياس داخل حسابك أو صفحات الطلب والدفع والبرامج، ولا نربطه ببياناتك الصحية أو الشخصية، ولا نستخدمه للإعلانات. تُعالَج بيانات القياس لدى Google، وهي مجهولة الهوية في غالبها (عنوان IP يُقنَّع، وبدون ميزات الإعلانات المخصصة). تقدر تسحب موافقتك بمسح بيانات الموقع من متصفحك، فيظهر لك الشريط مرة ثانية.$p$, updated_at = now()
 WHERE slug = 'privacy' AND body NOT LIKE '%Google Analytics%';
COMMIT;
